<?php
declare(strict_types=1);require dirname(__DIR__).'/app/bootstrap.php';admin_required();$id=max(0,scalar_int($_GET['id']??$_POST['id']??0));
if(is_post()&&$id){try{verify_csrf();support_ticket_admin_reply($id,(int)admin_user()['id'],scalar_string($_POST['message']??''),scalar_string($_POST['status']??'open'),scalar_string($_POST['priority']??'normal'),isset($_POST['send_sms']));flash('success','تیکت به‌روزرسانی شد.');}catch(Throwable $e){flash('error',$e->getMessage());}redirect(app_url('admin/tickets.php?id='.$id));}
$adminPage='tickets';$adminTitle='تیکت‌های پشتیبانی';
if($id){$stmt=db()->prepare('SELECT t.*,c.phone,c.full_name FROM support_tickets t JOIN customers c ON c.id=t.customer_id WHERE t.id=?');$stmt->execute([$id]);$ticket=$stmt->fetch();if(!$ticket){http_response_code(404);exit('تیکت پیدا نشد.');}$messages=support_ticket_messages($id);require __DIR__.'/partials/header.php';?>
<div class="admin-title"><div><h1><?=e($ticket['subject'])?></h1><p class="muted"><?=e($ticket['ticket_number'])?> · <?=e($ticket['full_name']?:$ticket['phone'])?></p></div><a class="btn btn-secondary" href="<?=e(app_url('admin/tickets.php'))?>">همه تیکت‌ها</a></div><div class="ticket-thread"><?php foreach($messages as $message):?><article class="ticket-message <?=$message['sender_type']==='admin'?'ticket-message--admin':'ticket-message--customer'?>"><header><strong><?=$message['sender_type']==='admin'?e($message['admin_name']?:'پشتیبانی'):e($message['customer_name']?:'مشتری')?></strong><small><?=e(jalali_format($message['created_at']))?></small></header><p><?=nl2br(e($message['message']))?></p></article><?php endforeach?></div><form method="post" class="card"><?=csrf_field()?><input type="hidden" name="id" value="<?=$id?>"><div class="form-grid"><div class="field full"><label>پاسخ پشتیبانی؛ برای تغییر وضعیت بدون پاسخ خالی بگذارید</label><textarea name="message" maxlength="5000" rows="6"></textarea></div><div class="field"><label>وضعیت</label><select name="status"><?php foreach(ticket_status_labels() as $key=>$label):?><option value="<?=$key?>" <?=$ticket['status']===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></div><div class="field"><label>اولویت</label><select name="priority"><?php foreach(ticket_priority_labels() as $key=>$label):?><option value="<?=$key?>" <?=$ticket['priority']===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select></div><div class="field full"><label><input type="checkbox" name="send_sms" value="1" checked> در صورت ثبت پاسخ، پیامک اطلاع‌رسانی ارسال شود</label></div></div><button class="btn btn-primary">ذخیره و ارسال پاسخ</button></form><?php require __DIR__.'/partials/footer.php';exit;}
$status=scalar_string($_GET['status']??'');$priority=scalar_string($_GET['priority']??'');$where=[];$params=[];if(isset(ticket_status_labels()[$status])){$where[]='t.status=?';$params[]=$status;}if(isset(ticket_priority_labels()[$priority])){$where[]='t.priority=?';$params[]=$priority;}$sql=$where?' WHERE '.implode(' AND ',$where):'';$stmt=db()->prepare('SELECT t.*,c.phone,c.full_name,(SELECT COUNT(*) FROM support_ticket_messages m WHERE m.ticket_id=t.id) message_count FROM support_tickets t JOIN customers c ON c.id=t.customer_id'.$sql.' ORDER BY FIELD(t.priority,\'urgent\',\'high\',\'normal\',\'low\'),t.last_message_at DESC LIMIT 500');$stmt->execute($params);$tickets=$stmt->fetchAll();require __DIR__.'/partials/header.php';?>
<div class="admin-title"><div><h1>تیکت‌های پشتیبانی</h1><p class="muted">گفت‌وگوی دوطرفه با وضعیت، اولویت و پیامک پاسخ.</p></div></div><form class="filters-admin"><select name="status"><option value="">همه وضعیت‌ها</option><?php foreach(ticket_status_labels() as $key=>$label):?><option value="<?=$key?>" <?=$status===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select><select name="priority"><option value="">همه اولویت‌ها</option><?php foreach(ticket_priority_labels() as $key=>$label):?><option value="<?=$key?>" <?=$priority===$key?'selected':''?>><?=e($label)?></option><?php endforeach?></select><button class="btn btn-secondary">اعمال</button></form><div class="table-wrap"><table><thead><tr><th>شماره</th><th>مشتری</th><th>موضوع</th><th>وضعیت</th><th>اولویت</th><th>پیام‌ها</th><th>آخرین پیام</th></tr></thead><tbody><?php foreach($tickets as $ticket):?><tr><td><a href="<?=e(app_url('admin/tickets.php?id='.(int)$ticket['id']))?>"><strong><?=e($ticket['ticket_number'])?></strong></a></td><td><?=e($ticket['full_name']?:$ticket['phone'])?></td><td><?=e($ticket['subject'])?></td><td><?=e(ticket_status_labels()[$ticket['status']]??$ticket['status'])?></td><td><?=e(ticket_priority_labels()[$ticket['priority']]??$ticket['priority'])?></td><td><?=fa_number((int)$ticket['message_count'])?></td><td><?=e(jalali_format($ticket['last_message_at']))?></td></tr><?php endforeach?><?php if(!$tickets):?><tr><td colspan="7">تیکتی پیدا نشد.</td></tr><?php endif?></tbody></table></div><?php require __DIR__.'/partials/footer.php';
